import{_ as t,c as o,o as a,ae as r}from"./chunks/framework.DI6M9D4h.js";const s="/assets/pcb-bottom-1.Dc6yD5q6.jpg",i="/assets/smd-diode-direction-1.5pqq2ES9.png",l="/assets/ws2812-direction-1.BUBuiPBW.png",p="/assets/pcb-top-1.YCoD0Rhb.jpg",n="/assets/pro-micro-socket-1.CZNHBGok.jpg",h="/assets/pro-micro-clone-puchi-c-1.BCyrfF3G.jpg",c="/assets/stabilizer-sticker-1.BOUwB1Cz.jpg",d="/assets/stabilizer-sticker-2.Deqe8O7X.jpg",m="/assets/top-plate-1.C9EeHZq_.jpg",g="/assets/top-plate-2.BhSWd49F.jpg",u="/assets/top-plate-3.CMfGkUKE.jpg",b="/assets/top-plate-4.Cw1c6Skz.jpg",f="/assets/protection-cover-1.Bfiscz24.jpg",k="/assets/protection-cover-2.FVATEXgC.jpg",_="/assets/protection-cover-3.DynHpFn9.jpg",y="/assets/bottom-plate-1.BGlY1ER5.jpg",w="/assets/bottom-plate-2.B6tikr_K.jpg",C=JSON.parse('{"title":"Reviung41 Build-Guide","description":"","frontmatter":{},"headers":[],"relativePath":"build-guides/reviung41/index.md","filePath":"build-guides/reviung41/index.md","lastUpdated":1754313225000}'),q={name:"build-guides/reviung41/index.md"};function P(v,e,x,z,S,B){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="reviung41-build-guide" tabindex="-1">Reviung41 Build-Guide <a class="header-anchor" href="#reviung41-build-guide" aria-label="Permalink to &quot;Reviung41 Build-Guide&quot;">​</a></h1><p><img src="https://img.shields.io/badge/PRs-welcome-brightgreen.svg?style=flat-square" alt="Pull Request&#39;s are welcome" loading="lazy"> <a href="https://discord.gg/frjFXZB" title="Redirect to Keycapsss Discord" target="_blank" rel="noreferrer"><img src="https://img.shields.io/discord/548530462419582996?style=flat-square&amp;logo=discord&amp;logoColor=white" alt="Discord" loading="lazy"></a></p><p><a href="https://reviung.com/build-guide/391/" target="_blank" rel="noreferrer">Japanese Build-Guide</a></p><h2 id="solder-parts-on-bottom-side" tabindex="-1">Solder parts on bottom side <a class="header-anchor" href="#solder-parts-on-bottom-side" aria-label="Permalink to &quot;Solder parts on bottom side&quot;">​</a></h2><p><img src="'+s+'" alt="PCB bottom" loading="lazy"></p><p>Solder the 41 hot-swap sockets, 41x SMD diodes and the 10x WS2812 led&#39;s to the bottom side.</p><p>Pay attention to orientation, SMD diodes and WS2812 led&#39;s are polarized. If the orientation is incorrect, the key will not respond, or led will not light up.</p><p>Solder the diode as shown in the following figure. <img src="'+i+'" alt="Diode direction" loading="lazy"></p><p>Solder the WS2812 led&#39;s as shown in the following figure.<br><a href="https://twitter.com/GTIPS_SH/status/1204244088867807234?s=20" target="_blank" rel="noreferrer">Video: How to solder the WS2812 led&#39;s.</a></p><p><img src="'+l+'" alt="WS2812 direction" loading="lazy"></p><h2 id="solder-parts-on-top-side" tabindex="-1">Solder parts on top side <a class="header-anchor" href="#solder-parts-on-top-side" aria-label="Permalink to &quot;Solder parts on top side&quot;">​</a></h2><p>Solder 1x WS2812 led to the top side. Pay attention to orientation, WS2812 led&#39;s are polarized.<br> Check the image below.</p><p><img src="'+p+'" alt="PCB" loading="lazy"></p><p><strong>I strongly recommend to use sockets for the Pro Micro.</strong><br> If something went wrong, it&#39;s much easier to replace the Pro Micro.</p><p><a href="https://keycapsss.com/keyboard-parts/parts/100/single-row-socket-headers-pins-mill-max-series-315" target="_blank" rel="noreferrer">Mill-Max Single Row Socket Headers</a> or <a href="https://keycapsss.com/keyboard-parts/parts/91/spring-loaded-pin-headers-12-pin-2pcs-conthrough" target="_blank" rel="noreferrer">Spring-loaded pin headers</a> will work.</p><h2 id="attach-the-pro-micro-with-sockets" tabindex="-1">Attach the Pro Micro (with sockets) <a class="header-anchor" href="#attach-the-pro-micro-with-sockets" aria-label="Permalink to &quot;Attach the Pro Micro (with sockets)&quot;">​</a></h2><p><strong>Before installing the Pro Micro, no matter which (can also happen on the Elite C, or Puchi-C), check whether they are working by plugging them in and <a href="#flash-qmk-firmware">flashing the default keymap</a>.</strong></p><p>Insert the pins (you can also use legs from through hole diodes/resistor) with a plier into the sockets.</p><p><img src="'+n+'" alt="" loading="lazy"></p><p>Place the Pro Micro (Micro-USB socket facing down).<br> Solder the pins and shorten the pins with diagonal pliers.</p><p><img src="'+h+'" alt="Pro Micro clone Puchi-C" loading="lazy"></p><h2 id="optional-install-the-2u-stabilizer" tabindex="-1">Optional: Install the 2U stabilizer <a class="header-anchor" href="#optional-install-the-2u-stabilizer" aria-label="Permalink to &quot;Optional: Install the 2U stabilizer&quot;">​</a></h2><p>The stabilizer is optional, but improves the feeling.</p><p>To improve the sound of the stabilizer, i recommend to attach a <a href="https://keycapsss.com/keyboard-parts/parts/137/stabilizer-foam-sticker" target="_blank" rel="noreferrer">foam sticker</a>.</p><p><img src="'+c+'" alt="" loading="lazy"></p><p><img src="'+d+'" alt="" loading="lazy"></p><h2 id="top-plate-assembly" tabindex="-1">Top plate assembly <a class="header-anchor" href="#top-plate-assembly" aria-label="Permalink to &quot;Top plate assembly&quot;">​</a></h2><p>Insert all switches of your choice (MX and clones) into the top plate.</p><p><img src="'+m+'" alt="Top plate with switches" loading="lazy"></p><p>Attach the 11x 8mm spacer to the top plate with the M2x5mm screws.</p><p><img src="'+g+'" alt="Top plate standoff" loading="lazy"></p><p>Put the top acrylic plate on mid pcb like on the image below.</p><p><img src="'+u+'" alt="" loading="lazy"></p><p>Check that all pins from the switches are straight and not bent. This is important that all pins move into the switch sockets in the next step.</p><p>Put the top plate with the switches on the two plates from the previous step.<br> Confirming that there are no bends in the switch pins.</p><p><img src="'+b+'" alt="" loading="lazy"></p><h2 id="attach-the-protection-cover" tabindex="-1">Attach the protection cover <a class="header-anchor" href="#attach-the-protection-cover" aria-label="Permalink to &quot;Attach the protection cover&quot;">​</a></h2><p>You need 3x M2x4mm screws, 3x4mm spacer and 3x M2x8mm screws and the 2mm acrylic cover.</p><p><img src="'+f+'" alt="Parts for the acrylic cover" loading="lazy"></p><p>Fasten the spacer with the 4mm screws like on the image.</p><p><img src="'+k+'" alt="Parts for the acrylic cover" loading="lazy"></p><p>Place the protection cover on the top side of the pcb and fasten it with the 8mm screws from the bottom side.</p><p><img src="'+_+'" alt="Parts for the acrylic cover" loading="lazy"></p><h2 id="bottom-plate-assembly" tabindex="-1">Bottom plate assembly <a class="header-anchor" href="#bottom-plate-assembly" aria-label="Permalink to &quot;Bottom plate assembly&quot;">​</a></h2><p>Put the inner bottom acrylic plate on mid pcb from the bottom.</p><p><img src="'+y+'" alt="inner bottom plate" loading="lazy"></p><p>Put the bottom acrylic plate on the bottom and fasten it with 11x M2x5mm screws.</p><p><img src="'+w+`" alt="bottom plate" loading="lazy"></p><p>Attach the rubber feed to the bottom plate.</p><h2 id="flash-qmk-firmware" tabindex="-1">Flash QMK firmware <a class="header-anchor" href="#flash-qmk-firmware" aria-label="Permalink to &quot;Flash QMK firmware&quot;">​</a></h2><p>The board requires a keymap in order to function. This section assumes that you&#39;re familiar with keymaps and the use of the QMK tool. If not, please refer to the QMK <a href="https://docs.qmk.fm/#/getting_started_build_tools" target="_blank" rel="noreferrer">&quot;Getting Started&quot; guide</a>.</p><p>The <a href="https://github.com/qmk/qmk_toolbox/releases" target="_blank" rel="noreferrer">QMK Toolbox</a> can be used to write non-customized keymaps via a GUI, avoiding the need to configure a local QMK environment. (For custom keymaps, it&#39;s recommended to build the full environment described above).</p><p>Clone/download the QMK firmware and execute the following in the <a href="https://github.com/qmk/qmk_firmware" target="_blank" rel="noreferrer">qmk_firmware</a> directory to write the default Reviung41 keymap.</p><pre><code>make reviung41:default:flash
</code></pre><p>When <code>Detecting USB port, reset your controller now...</code> is displayed, press the reset button on the keyboard to start writing.</p><p><a href="https://github.com/qmk/qmk_firmware/blob/master/keyboards/reviung41/keymaps/default/keymap.c" target="_blank" rel="noreferrer">Default Keymap File</a></p>`,56)])])}const T=t(q,[["render",P]]);export{C as __pageData,T as default};
